<script>
(() => {
  const boardElement = document.getElementById('board');
  const scoreElement = document.getElementById('score');
  const bestElement = document.getElementById('best');
  let grid = [
    [0, 0, 2, 0],
    [0, 0, 0, 0],
    [0, 2, 4, 2],
    [0, 0, 8, 2]
  ];
  let score = 20;
  let best = 20;
  let cupcakeMode = false;

  function render() {
    boardElement.innerHTML = '';
    grid.forEach(row => row.forEach(value => {
      const cell = document.createElement('div');
      cell.className = 'cell' + (value ? ' v' + value : '');
      cell.textContent = value || '';
      boardElement.appendChild(cell);
    }));
    scoreElement.textContent = score;
    bestElement.textContent = best;
  }

  function addTile() {
    const empty = [];
    grid.forEach((row, r) => row.forEach((value, c) => { if (!value) empty.push([r, c]); }));
    if (!empty.length) return;
    const [r, c] = empty[Math.floor(Math.random() * empty.length)];
    grid[r][c] = Math.random() < 0.9 ? 2 : 4;
  }

  function move(direction) {
    const before = JSON.stringify(grid);
    let gained = 0;
    for (let i = 0; i < 4; i++) {
      let line = [];
      for (let j = 0; j < 4; j++) {
        const r = direction === 'up' ? j : direction === 'down' ? 3 - j : i;
        const c = direction === 'left' ? j : direction === 'right' ? 3 - j : i;
        line.push(grid[r][c]);
      }
      const compact = line.filter(Boolean);
      const merged = [];
      for (let j = 0; j < compact.length; j++) {
        if (compact[j] === compact[j + 1]) {
          merged.push(compact[j] * 2);
          gained += compact[j] * 2;
          j++;
        } else merged.push(compact[j]);
      }
      while (merged.length < 4) merged.push(0);
      for (let j = 0; j < 4; j++) {
        const r = direction === 'up' ? j : direction === 'down' ? 3 - j : i;
        const c = direction === 'left' ? j : direction === 'right' ? 3 - j : i;
        grid[r][c] = merged[j];
      }
    }
    if (JSON.stringify(grid) !== before) {
      score += gained;
      best = Math.max(best, score);
      addTile();
      render();
    }
  }

  function startNewGame() {
    grid = Array.from({length: 4}, () => [0, 0, 0, 0]);
    score = 0;
    addTile();
    addTile();
    render();
  }

  document.addEventListener('keydown', event => {
    const keys = {
      ArrowUp: 'up', w: 'up', W: 'up',
      ArrowDown: 'down', s: 'down', S: 'down',
      ArrowLeft: 'left', a: 'left', A: 'left',
      ArrowRight: 'right', d: 'right', D: 'right'
    };
    if (keys[event.key]) {
      event.preventDefault();
      move(keys[event.key]);
    }
  });

  let touchStart = null;
  boardElement.addEventListener('touchstart', event => {
    const touch = event.changedTouches[0];
    touchStart = [touch.clientX, touch.clientY];
  }, {passive: true});
  boardElement.addEventListener('touchend', event => {
    if (!touchStart) return;
    const touch = event.changedTouches[0];
    const dx = touch.clientX - touchStart[0];
    const dy = touch.clientY - touchStart[1];
    if (Math.max(Math.abs(dx), Math.abs(dy)) > 25) {
      move(Math.abs(dx) > Math.abs(dy) ? (dx > 0 ? 'right' : 'left') : (dy > 0 ? 'down' : 'up'));
    }
    touchStart = null;
  }, {passive: true});

  document.getElementById('newGame').addEventListener('click', startNewGame);
  const classicTab = document.getElementById('classicTab');
  const cupcakeTab = document.getElementById('cupcakeTab');
  classicTab.addEventListener('click', () => {
    cupcakeMode = false;
    document.body.classList.remove('cupcakes');
    classicTab.classList.add('active');
    cupcakeTab.classList.remove('active');
  });
  cupcakeTab.addEventListener('click', () => {
    cupcakeMode = true;
    document.body.classList.add('cupcakes');
    cupcakeTab.classList.add('active');
    classicTab.classList.remove('active');
  });
  document.querySelectorAll('.game-link').forEach(link => link.addEventListener('click', event => event.preventDefault()));
  render();
})();
</script>
